def fusion_framework_hints(spec: FusionPatternSpec) -> set[str]:
    text = normalize_text(spec.candidate_path).lower()
    hints: set[str] = set()
    if "vllm/" in text:
        hints.add("vllm")
    if any(token in text for token in ("tokenspeed/", "tokenspeed-", "tokenspeed_")):
        hints.add("tokenspeed")
    if "tensorrt_llm/" in text:
        hints.add("trtllm")
    if any(token in text for token in ("python/sglang/", "sgl_kernel/")):
        hints.add("sglang")
    return hints


